/**
 * Aset biner (PNG) yang ditanam sebagai base64.
 *
 * Alasan: deployment Vercel pada project ini dikirim lewat API 'files' yang
 * hanya menerima berkas teks, sehingga logo/ikon tidak bisa diunggah sebagai
 * biner. Dengan menanamkannya di modul ini, rute statis tetap berfungsi
 * (logo, favicon, ikon PWA) tanpa bergantung pada folder public/.
 */
const ASSETS = {
  '/logo-d4tech.png': { mime: 'image/png', base64: '' },
  '/icon-192.png': { mime: 'image/png', base64: '' },
  '/icon-512.png': { mime: 'image/png', base64: '' },
  '/favicon.png': { mime: 'image/png', base64: '' },
};

module.exports = ASSETS;
